/** Shown on any value, chart point or card whose is_synthetic is true. */
export const SYNTHETIC_TIP =
  'Synthetic demo data: generated by the dataset pipeline, not official statistics. Treat figures as illustrative.';

export function SyntheticBadge({ show = true, compact = false, align = 'center' }: { show?: boolean; compact?: boolean; align?: 'center' | 'right' }) {
  if (!show) return null;
  return (
    <span className="group relative inline-flex align-middle">
      <span
        tabIndex={0}
        role="note"
        aria-label={SYNTHETIC_TIP}
        className="inline-flex items-center gap-1 rounded-full border border-marigold/50 bg-marigold/10 px-1.5 py-px text-[9.5px] font-semibold uppercase tracking-wider text-marigold"
      >
        <span aria-hidden className="h-1.5 w-1.5 rounded-full bg-marigold" />
        {compact ? 'Syn' : 'Synthetic'}
      </span>
      <span
        role="tooltip"
        className={`pointer-events-none absolute top-full z-50 mt-1.5 hidden w-56 rounded-lg border border-line bg-surface p-2 text-[11px] font-normal normal-case leading-snug tracking-normal text-muted shadow-lg group-focus-within:block group-hover:block ${align === 'right' ? 'right-0' : 'left-1/2 -translate-x-1/2'}`}
      >
        {SYNTHETIC_TIP}
      </span>
    </span>
  );
}

/** HTML string version for ECharts tooltips. */
export const syntheticBadgeHtml =
  '<span style="display:inline-block;margin-left:6px;padding:0 6px;border:1px solid rgba(251,191,36,.5);border-radius:99px;font-size:9px;letter-spacing:.06em;color:#fbbf24;background:rgba(251,191,36,.1)">SYNTHETIC</span>';
